public class TransformingIterator {

    public static <T1, T2> Iterator<T2> createFilteredTransformingIterator(
            final Iterable<T1> c,
            final Function<T1, T2> trans,
            final boolean readOnly,
            final BooleanSupplier... p
    ) {
        return new Iterator<T2>() {
            private final Iterator<T1> iterator = c.iterator();
            private T1 current;

            @Override
            public boolean hasNext() {
                advanceToNextNonFilteredElement();
                return current != null;
            }

            @Override
            public T2 next() {
                if (!hasNext()) {
                    throw new java.util.NoSuchElementException();
                }
                T2 result = trans.apply(current);
                advanceToNextNonFilteredElement();
                return result;
            }

            private void advanceToNextNonFilteredElement() {
                do {
                    if (!iterator.hasNext()) {
                        current = null;
                        return;
                    }
                    current = iterator.next();
                } while (matchesAnyFilter());
            }

            private boolean matchesAnyFilter() {
                for (BooleanSupplier pred : p) {
                    if (pred.getAsBoolean()) {
                        return true;
                    }
                }
                return false;
            }

            @Override
            public void remove() {
                if (readOnly) {
                    throw new java.lang.UnsupportedOperationException();
                }
                iterator.remove();
            }
        };
    }

